import { cbc, ctr, gcm } from '@noble/ciphers/aes'
import { aesInitCheck, aesParamsCheck, aesMethods } from './utils/aes.mjs'
import { createCipherApi } from './utils/cipher.mjs'

// noble-based implementation

function aesNobleType(mode) {
  if (mode === 'CBC') return cbc
  if (mode === 'CTR') return ctr
  if (mode === 'GCM') return gcm
  throw new Error('Unexpected AES mode')
}

export async function aes(mode, key, usage) {
  aesInitCheck(mode, key, usage)
  const method = aesNobleType(mode)

  return createCipherApi(usage, {
    async encrypt(data, nonce, additionalData) {
      aesParamsCheck(mode, nonce, additionalData)
      return method(key, nonce, additionalData).encrypt(data)
    },
    async decrypt(data, nonce, additionalData) {
      aesParamsCheck(mode, nonce, additionalData)
      return method(key, nonce, additionalData).decrypt(data)
    },
  })
}

const { encryptCBC, decryptCBC, encryptCTR, decryptCTR, encryptGCM, decryptGCM } = aesMethods(aes)

export { encryptCBC, decryptCBC, encryptCTR, decryptCTR, encryptGCM, decryptGCM }
